INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch09$PT142-S1-Q3$batch09$, 142, 1, 3, $batch09$Principle-Conform$batch09$, $batch09$Editorial: The government should not fund any part of its health services with lottery revenue. These health services are essential to our community, but lottery revenue could decline at some time in the future, leaving the government scrambling to make up a budget shortfall.$batch09$, $batch09$The argument in the editorial most closely conforms to which one of the following principles?$batch09$, $batch09$B$batch09$, true, $batch09$Batch 09; question text from local bank.$batch09$ FROM lr_sections s WHERE s.preptest=142 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT142-S1-Q3$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$A$batch09$, $batch09$Governments should spend more of their revenue on essential services than on nonessential services.$batch09$, $batch09$Not the Reasoning$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT142-S1-Q3$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$A$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$B$batch09$, $batch09$Essential government services must be funded from reliable sources of revenue.$batch09$, $batch09$Correct$batch09$, true FROM lr_questions q WHERE q.qid=$batch09$PT142-S1-Q3$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$B$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$C$batch09$, $batch09$No government service should be entirely dependent on lottery revenue for its funding.$batch09$, $batch09$Too Weak$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT142-S1-Q3$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$C$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$D$batch09$, $batch09$Governments should consider all health services to be essential to the community.$batch09$, $batch09$Not the Reasoning$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT142-S1-Q3$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$D$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$E$batch09$, $batch09$At least some lottery revenue must be set aside in case of budget shortfalls in the future.$batch09$, $batch09$Different Remedy$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT142-S1-Q3$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$E$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT142-S1-Q3$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Conclusion$batch09$, $batch09$The government shouldn't fund any part of its health services with lottery revenue.$batch09$), (1, $batch09$Evidence$batch09$, $batch09$The health services are essential, and lottery revenue could decline, leaving a budget shortfall.$batch09$), (2, $batch09$Evaluate$batch09$, $batch09$Two facts lead to the conclusion. These services are essential, and lottery money is unreliable. The principle puts them together: essential services need reliable funding. Lottery money isn't reliable, so none of it should pay for them.$batch09$), (3, $batch09$Goal$batch09$, $batch09$Essential services should be funded only from reliable sources.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT142-S1-Q3$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$The editorial never compares spending on essential and nonessential services.$batch09$), ($batch09$B$batch09$, $batch09$The health services are essential, so they must be funded from reliable sources. Lottery revenue could decline, so it isn't reliable. That rules out using lottery money for any part of them, which is the conclusion.$batch09$), ($batch09$C$batch09$, $batch09$This bans being "entirely" dependent on lottery money. The editorial bans funding "any part" of the services that way. Under C, partial lottery funding would be fine.$batch09$), ($batch09$D$batch09$, $batch09$The editorial says these health services are essential. It doesn't say every health service must be treated that way.$batch09$), ($batch09$E$batch09$, $batch09$This saves lottery money for future shortfalls. The editorial's answer is to stop relying on lottery money for these services at all.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT142-S1-Q3$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
